using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.Rendering; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class CoursesController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(string? q,int page=1){const int size=10;var x=db.Courses.Include(c=>c.Category).AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.CourseName.Contains(q)||c.CourseCode.Contains(q));ViewBag.Page=page;ViewBag.Total=(int)Math.Ceiling(await x.CountAsync()/(double)size);return View(await x.OrderByDescending(c=>c.CreatedAt).Skip((page-1)*size).Take(size).ToListAsync());} public async Task<IActionResult> Create(){await Lists();return View("Form",new Course());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Course m){if(await db.Courses.AnyAsync(x=>x.CourseCode==m.CourseCode))ModelState.AddModelError(nameof(m.CourseCode),"Mã khóa học đã tồn tại.");if(!ModelState.IsValid){await Lists();return View("Form",m);}db.Add(m);await db.SaveChangesAsync();TempData["Success"]="Đã thêm khóa học.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var m=await db.Courses.FindAsync(id);if(m==null)return NotFound();await Lists();return View("Form",m);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Course m){if(id!=m.CourseId)return BadRequest();if(!ModelState.IsValid){await Lists();return View("Form",m);}m.UpdatedAt=DateTime.UtcNow;db.Update(m);await db.SaveChangesAsync();TempData["Success"]="Đã cập nhật khóa học.";return RedirectToAction(nameof(Index));} private async Task Lists()=>ViewBag.Categories=new SelectList(await db.Categories.Where(x=>x.IsActive).ToListAsync(),"CategoryId","CategoryName"); }
